  committed: true,
  conflict: false,
  slug: prepared.slug,
  title: prepared.title,
  isRepublish: prepared.isRepublish,
  commitSha: String(commit.sha || '').slice(0, 12),
  expectedUrl: prepared.expectedUrl,
  draftPutBody: prepared.draftPutBody,
  message: 'Published ' + prepared.slug + '.'
} }];

