  slug: gate.slug,
  status: response.statusCode,
  message: ok
    ? 'Draft ' + gate.slug + ' updated (' + gate.decision + '). Nothing was published.'
    : 'Could not update the draft (HTTP ' + response.statusCode + ').'
} }];

